import{_ as a,o as n,a as p,b as l}from"./app.DKoEZOcr.js";const r=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"缓存控制","link":"/api/SIMD-API/c_api/cache_ctrl/cache_ctrl"},{"text":"asc_set_scalar_cache_mode","link":"/api/SIMD-API/c_api/cache_ctrl/asc_set_scalar_cache_mode"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/cache_ctrl/asc_set_scalar_cache_mode.md","filePath":"api/SIMD-API/c_api/cache_ctrl/asc_set_scalar_cache_mode.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"流水类型","slug":"流水类型","link":"#流水类型"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1787999811000}'),c={name:"api/SIMD-API/c_api/cache_ctrl/asc_set_scalar_cache_mode.md"};function e(t,s,_,i,o,d){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>asc_set_scalar_cache_mode</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>配置标量单元访问Global Memory时的L2 Cache管理策略。接口通过修改CTRL寄存器对应比特域生效：</p><ul><li>传入<a href="../defs/enum/asc_load_l2_cache_mode.html">asc_load_l2_cache_mode</a>时，设置标量读（load）策略。</li><li>传入<a href="../defs/enum/asc_store_l2_cache_mode.html">asc_store_l2_cache_mode</a>时，设置标量写（store）策略。</li></ul><p>设置后，后续标量路径上的GM读写将按该策略访问L2 Cache，直至再次调用本接口修改。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_set_scalar_cache_mode</span><span class="p">(</span><span class="n">asc_load_l2_cache_mode</span><span class="w"> </span><span class="n">l2_cache_mode</span><span class="p">)</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_set_scalar_cache_mode</span><span class="p">(</span><span class="n">asc_store_l2_cache_mode</span><span class="w"> </span><span class="n">l2_cache_mode</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><table><thead><tr><th align="left">参数名</th><th align="left">输入/输出</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">l2_cache_mode</td><td align="left">输入</td><td align="left">L2 Cache管理策略。load重载传入<a href="../defs/enum/asc_load_l2_cache_mode.html">asc_load_l2_cache_mode</a>枚举值；store重载传入<a href="../defs/enum/asc_store_l2_cache_mode.html">asc_store_l2_cache_mode</a>枚举值。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="流水类型">流水类型<a class="header-anchor" href="#流水类型">​</a></h2><p>PIPE_S</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>本接口仅影响<strong>标量访存路径</strong>的L2 Cache默认策略，不会修改向量搬运类接口（如<a href="../vector_datamove/asc_copy_gm2ub_align/asc_copy_gm2ub_align_arch_3510.html">asc_copy_gm2ub_align</a>、<a href="../vector_datamove/asc_copy_ub2gm_align/asc_copy_ub2gm_align_arch_3510.html">asc_copy_ub2gm_align</a>、<a href="../vector_datamove/asc_ndim_copy_gm2ub.html">asc_ndim_copy_gm2ub</a>等）参数中的<code>l2_cache_mode</code>；二者相互独立。大块tile数据的L2 Cache优化应通过向量搬运入参配置，参见<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/02_simd_c_api/02_features/00_data_movement/00_set_l2_cache_mode">L2 Cache Mode最佳实践样例</a>。</li><li>load与store策略分属CTRL不同比特域，设置其一不会覆盖另一侧已配置的值。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><ul><li>场景A：标量load — <code>NORMAL_FIRST_VICTIM</code>+循环内重复读GM tiling表</li></ul><p>动态tiling存放在GM上：<code>tiling_gm[0]</code>为<code>tile_count</code>，后续依次为各tile的<code>length</code>与<code>offset</code>。循环内每个tile都会标量读取tiling字段，同一tiling区域会被多次访问，适合启用L2复用。若tiling字段只读一次、后续不再访问，应改用<code>NOTALLOC_KEEP</code>或无需调用本接口。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__gm__</span><span class="w"> </span><span class="kt">int32_t</span><span class="o">*</span><span class="w"> </span><span class="n">tiling_gm</span><span class="p">;</span><span class="w">   </span><span class="c1">// [tile_count, len[0..n-1], off[0..n-1]]</span>
<span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">src_gm</span><span class="p">;</span>
<span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">dst_ub</span><span class="p">;</span>

<span class="c1">// SIMD_VF外：tiling表将在循环内被多次标量读取</span>
<span class="n">asc_set_scalar_cache_mode</span><span class="p">(</span><span class="n">asc_load_l2_cache_mode</span><span class="o">::</span><span class="n">NORMAL_FIRST_VICTIM</span><span class="p">);</span>

<span class="kt">int32_t</span><span class="w"> </span><span class="n">tile_count</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">tiling_gm</span><span class="p">[</span><span class="mi">0</span><span class="p">];</span>
<span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">int32_t</span><span class="w"> </span><span class="n">tile</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">tile</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">tile_count</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">tile</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">tile_len</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">tiling_gm</span><span class="p">[</span><span class="mi">1</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">tile</span><span class="p">];</span><span class="w">              </span><span class="c1">// 每tile标量读GM</span>
<span class="w">    </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">tile_off</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">tiling_gm</span><span class="p">[</span><span class="mi">1</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">tile_count</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">tile</span><span class="p">];</span><span class="w"> </span><span class="c1">// 每tile标量读GM</span>
<span class="w">    </span><span class="n">asc_copy_gm2ub_align</span><span class="p">(</span><span class="n">dst_ub</span><span class="p">,</span><span class="w"> </span><span class="n">src_gm</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">tile_off</span><span class="p">,</span><span class="w"> </span><span class="n">tile_len</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">));</span>
<span class="w">    </span><span class="c1">// 向量搬运的l2_cache_mode由asc_copy_gm2ub_align单独配置，见set_l2_cache_mode样例</span>
<span class="w">    </span><span class="c1">// ... 向量计算 ...</span>
<span class="p">}</span>
</code></pre></div><ul><li>场景B：标量store — <code>NOTALLOC_CLEAN</code>+标量写GM</li></ul><p>多核算子向GM统计counter做标量原子累加时，临时关闭标量写路径的L2分配，避免对控制字段产生不必要的Cache Line分配。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__gm__</span><span class="w"> </span><span class="kt">int32_t</span><span class="o">*</span><span class="w"> </span><span class="n">counter_gm</span><span class="p">;</span><span class="w">  </span><span class="c1">// GM上的多核共享计数器</span>

<span class="n">asc_set_scalar_cache_mode</span><span class="p">(</span><span class="n">asc_store_l2_cache_mode</span><span class="o">::</span><span class="n">NOTALLOC_CLEAN</span><span class="p">);</span>
<span class="n">asc_dcci_entire_all</span><span class="p">();</span><span class="w">       </span><span class="c1">// 标量原子操作前保证DCache一致性</span>
<span class="n">asc_atomic_add</span><span class="p">(</span><span class="n">counter_gm</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const m=a(c,[["render",e]]);export{r as __pageData,m as default};
